use std::alloc::{GlobalAlloc, Layout, System};
use std::io::{self, Write};
use std::sync::atomic::{AtomicUsize, Ordering};
use std::time::Instant;
use pine_runtime::{Bar, HistoricalRuntime, RuntimeResult, write_public_runtime_result_json};

struct Allocator;
static LIVE: AtomicUsize = AtomicUsize::new(0);
static PEAK: AtomicUsize = AtomicUsize::new(0);
static TOTAL: AtomicUsize = AtomicUsize::new(0);
static COUNT: AtomicUsize = AtomicUsize::new(0);
static LARGEST: AtomicUsize = AtomicUsize::new(0);
unsafe impl GlobalAlloc for Allocator {
    unsafe fn alloc(&self, layout: Layout) -> *mut u8 {
        let pointer = unsafe { System.alloc(layout) };
        if !pointer.is_null() { added(layout.size()); }
        pointer
    }
    unsafe fn dealloc(&self, pointer: *mut u8, layout: Layout) {
        LIVE.fetch_sub(layout.size(), Ordering::Relaxed);
        unsafe { System.dealloc(pointer, layout); }
    }
    unsafe fn realloc(&self, pointer: *mut u8, layout: Layout, new_size: usize) -> *mut u8 {
        let next = unsafe { System.realloc(pointer, layout, new_size) };
        if !next.is_null() {
            LIVE.fetch_sub(layout.size(), Ordering::Relaxed);
            added(new_size);
        }
        next
    }
}
fn added(size: usize) {
    let live = LIVE.fetch_add(size, Ordering::Relaxed) + size;
    PEAK.fetch_max(live, Ordering::Relaxed);
    TOTAL.fetch_add(size, Ordering::Relaxed);
    COUNT.fetch_add(1, Ordering::Relaxed);
    LARGEST.fetch_max(size, Ordering::Relaxed);
}
#[global_allocator]
static ALLOCATOR: Allocator = Allocator;

#[cfg(windows)]
fn rss() -> (usize, usize) {
    #[repr(C)]
    struct Memory { size: u32, faults: u32, peak_working_set: usize, working_set: usize,
        paged_peak: usize, paged: usize, nonpaged_peak: usize, nonpaged: usize,
        pagefile: usize, pagefile_peak: usize }
    #[link(name="kernel32")]
    unsafe extern "system" { fn GetCurrentProcess() -> *mut core::ffi::c_void; }
    #[link(name="psapi")]
    unsafe extern "system" { fn GetProcessMemoryInfo(process: *mut core::ffi::c_void, memory: *mut Memory, size: u32) -> i32; }
    let mut memory: Memory = unsafe { std::mem::zeroed() };
    memory.size = std::mem::size_of::<Memory>() as u32;
    assert_ne!(unsafe { GetProcessMemoryInfo(GetCurrentProcess(), &mut memory, memory.size) }, 0);
    (memory.working_set, memory.peak_working_set)
}
#[cfg(not(windows))]
fn rss() -> (usize, usize) {
    let status = std::fs::read_to_string("/proc/self/status").unwrap();
    let read = |field: &str| status.lines().find_map(|line| line.strip_prefix(field).map(|value|
        value.split_whitespace().next().unwrap().parse::<usize>().unwrap() * 1024)).unwrap();
    (read("VmRSS:"), read("VmHWM:"))
}
fn measured<T>(name: &str, run: impl FnOnce() -> T) -> T {
    let start_live = LIVE.load(Ordering::Relaxed);
    let (start_rss, start_peak_rss) = rss();
    TOTAL.store(0, Ordering::Relaxed);
    COUNT.store(0, Ordering::Relaxed);
    LARGEST.store(0, Ordering::Relaxed);
    PEAK.store(start_live, Ordering::Relaxed);
    let start = Instant::now();
    let output = run();
    let ms = start.elapsed().as_secs_f64() * 1000.0;
    let live = LIVE.load(Ordering::Relaxed);
    let peak = PEAK.load(Ordering::Relaxed);
    let total = TOTAL.load(Ordering::Relaxed);
    let count = COUNT.load(Ordering::Relaxed);
    let largest = LARGEST.load(Ordering::Relaxed);
    let (end_rss, end_peak_rss) = rss();
    println!("{}", serde_json::json!({"stage":name,"ms":ms,"startLiveBytes":start_live,
        "retainedLiveBytes":live,"additionalPeakBytes":peak.saturating_sub(start_live),
        "allocatedBytes":total,"allocations":count,"largestAllocationBytes":largest,
        "startRssBytes":start_rss,"endRssBytes":end_rss,
        "startProcessPeakRssBytes":start_peak_rss,"endProcessPeakRssBytes":end_peak_rss}));
    output
}
struct Counter(usize);
impl Write for Counter {
    fn write(&mut self, bytes: &[u8]) -> io::Result<usize> { self.0 += bytes.len(); Ok(bytes.len()) }
    fn flush(&mut self) -> io::Result<()> { Ok(()) }
}
fn owned_json(result: &RuntimeResult) -> String {
    let mut counter = Counter(0);
    write_public_runtime_result_json(result, &mut counter).unwrap();
    let mut output = Vec::with_capacity(counter.0);
    write_public_runtime_result_json(result, &mut output).unwrap();
    String::from_utf8(output).unwrap()
}
fn pipeline(runtime: &HistoricalRuntime<'_>) -> String {
    #[cfg(not(borrowed_result))]
    { owned_json(&runtime.result()) }
    #[cfg(borrowed_result)]
    {
        use pine_runtime::write_public_runtime_result_view_json;
        let view = runtime.result_view();
        let mut counter = Counter(0);
        write_public_runtime_result_view_json(&view, &mut counter).unwrap();
        let mut bytes = Vec::with_capacity(counter.0);
        write_public_runtime_result_view_json(&view, &mut bytes).unwrap();
        String::from_utf8(bytes).unwrap()
    }
}
fn main() {
    let args = std::env::args().collect::<Vec<_>>();
    let script = std::fs::read_to_string(&args[1]).unwrap();
    let mode = args.get(2).map_or("staged", String::as_str);
    let n = args.get(3).map_or(100_000, |value| value.parse::<usize>().unwrap());
    let bars = measured("dataset", || (0..n).map(|i| { let close = 100. + (i % 997) as f64 * 0.01;
        Bar { time: i as i64 * 60_000, open: close - 0.2, high: close + 0.5,
            low: close - 0.5, close, volume: 100. + (i % 37) as f64 }
    }).collect::<Vec<_>>());
    let source = pine_syntax::SourceFile::new("result-output-heavy.pine", script);
    let hir = measured("analyze", || pine_sema::analyze_source(&source).hir.unwrap());
    let mut runtime = measured("init", || HistoricalRuntime::new(&hir));
    measured("seed", || runtime.append_bars(&bars).unwrap());
    if mode == "pipeline" {
        let json = measured("hostJsonPipeline", || pipeline(&runtime));
        let parsed: serde_json::Value = measured("parseJson", || serde_json::from_str(&json).unwrap());
        println!("{}", serde_json::json!({"mode":mode,"bars":n,"jsonBytes":json.len(),
            "plots":parsed["plots"].as_array().unwrap().len(),"profile":runtime.profile().plot_values}));
        std::hint::black_box((&runtime, &json, &parsed));
    } else {
        let checkpoint = measured("cowClone", || runtime.clone());
        let result = measured("ownedResult", || runtime.result());
        let json = measured("serializeOwnedResult", || owned_json(&result));
        let parsed: serde_json::Value = measured("parseJson", || serde_json::from_str(&json).unwrap());
        println!("{}", serde_json::json!({"mode":mode,"bars":n,"jsonBytes":json.len(),
            "plots":parsed["plots"].as_array().unwrap().len(),"profile":runtime.profile().plot_values}));
        std::hint::black_box((&runtime, &checkpoint, &result, &json, &parsed));
    }
}

