"""Run controlled, fresh-process before/after probes after source and gates freeze.

No compilation is performed. Every stdout/stderr/exit receipt is retained in a
unique run directory. An invalid or failed process prevents a success summary.
"""
from __future__ import annotations

import argparse
from dataclasses import dataclass
from datetime import datetime, timezone
import hashlib
import json
import math
from pathlib import Path
import re
import statistics
import subprocess
import time
import uuid

DIRECTORY = Path(__file__).resolve().parent
ROOT = DIRECTORY.parents[1]
TAGS = ("before", "after")
REPETITIONS = 3
DISPATCH_LINE = re.compile(r"bars=(\d+) appendMs=([0-9.]+) resultBytes=(\d+)")


@dataclass(frozen=True)
class Case:
    name: str
    group: str
    script: str
    bars: int
    mode: str
    repetitions: int = REPETITIONS


def digest(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def write_json(path: Path, value: object) -> None:
    temporary = path.with_suffix(path.suffix + ".tmp")
    temporary.write_text(json.dumps(value, indent=2, ensure_ascii=False, allow_nan=False), encoding="utf8")
    temporary.replace(path)


def pine(function: str, length: int, source: str = "close") -> str:
    return f'//@version=6\nindicator("{function} {length}")\nplot(ta.{function}({source}, {length}))\n'


def plan(include_controls: bool) -> tuple[list[Case], dict[str, str]]:
    cases: list[Case] = []
    scripts: dict[str, str] = {}
    for function in ("highest", "lowest", "highestbars", "lowestbars"):
        for length in (16, 512, 5000):
            name = f"{function}_{length}"
            file = f"bench-{name}.pine"
            scripts[file] = pine(function, length)
            cases.append(Case(name, "heap", file, 24_000, "historical"))
    for function in ("rci", "mode"):
        for length in (512, 5000):
            name = f"{function}_{length}"
            file = f"bench-{name}.pine"
            scripts[file] = pine(function, length)
            cases.append(Case(name, "heap", file, 6000, "historical"))
    for name, function in (("plot", None), ("sma14", "sma"), ("ema14", "ema"), ("rsi14", "rsi"), ("strategy", None)):
        file = f"bench-common-{name}.pine"
        if function:
            scripts[file] = pine(function, 14)
        else:
            declaration = "strategy" if name == "strategy" else "indicator"
            scripts[file] = f'//@version=6\n{declaration}("{name}")\nplot(close)\n'
        cases.append(Case(f"common_{name}", "heap", file, 100_000, "historical"))
    for name, function, source in (
        ("highest_descending_5000", "highest", "-bar_index"),
        ("lowest_ascending_5000", "lowest", "bar_index"),
    ):
        file = f"bench-{name}.pine"
        scripts[file] = pine(function, 5000, source)
        for mode in ("historical", "realtime", "retained"):
            cases.append(Case(f"{name}_{mode}", "heap", file, 24_000, mode))
    if include_controls:
        for function in ("wma", "stdev"):
            file = f"bench-control-{function}_512.pine"
            scripts[file] = pine(function, 512)
            cases.append(Case(f"unchanged_control_{function}_512", "heap", file, 20_000, "historical"))
    cases.append(Case("math_dispatch", "dispatch", "math_dispatch.pine", 20_000, "append"))
    for name, script in (
        ("output_heavy", "result-output-heavy.pine"),
        ("strategy_history", "result-strategy.pine"),
        ("drawing_history", "result-drawing-history.pine"),
    ):
        cases.append(Case(f"{name}_pipeline", "result", script, 100_000, "pipeline"))
        cases.append(Case(f"{name}_staged", "result", script, 100_000, "staged", 1))
    return cases, scripts


def prepare_scripts(scripts: dict[str, str]) -> None:
    for name, text in scripts.items():
        path = DIRECTORY / name
        if path.exists():
            if path.read_text(encoding="utf8") != text:
                raise RuntimeError(f"Generated source changed: {path}")
        else:
            path.write_text(text, encoding="utf8")


def probe_source(group: str) -> Path:
    return {
        "heap": DIRECTORY / "heap_probe.rs",
        "dispatch": DIRECTORY / "dispatch_probe.rs",
        "result": DIRECTORY / "result_probe.rs",
    }[group]


def identity(group: str, tag: str) -> dict:
    binary = DIRECTORY / f"{group}-{tag}.exe"
    source = probe_source(group)
    link_path = DIRECTORY / f"identity-{group}-{tag}.json"
    for path in (binary, source, link_path):
        if not path.is_file():
            raise FileNotFoundError(path)
    link = json.loads(link_path.read_text(encoding="utf-8-sig"))
    binary_hash = digest(binary)
    source_hash = digest(source)
    if link["executableSha256"] != binary_hash or link["sourceSha256"] != source_hash:
        raise RuntimeError(f"Linked source or binary does not match receipt: {link_path}")
    return {"binary": str(binary), "binarySha256": binary_hash, "probeSource": str(source),
            "probeSourceSha256": source_hash, "linkReceipt": str(link_path),
            "linkReceiptSha256": digest(link_path), "link": link}


def json_lines(raw: bytes) -> list[dict]:
    lines = raw.decode("utf8").splitlines()
    if not lines or any(not line.strip() for line in lines):
        raise ValueError("Expected nonempty JSONL output")
    result = [json.loads(line) for line in lines]
    if any(not isinstance(value, dict) for value in result):
        raise ValueError("Probe output is not a JSON object")
    return result


def numeric(value: object) -> bool:
    return isinstance(value, (float, int)) and not isinstance(value, bool)


def check_numbers(record: dict) -> None:
    for key, value in record.items():
        if numeric(value) and (not math.isfinite(value) or value < 0):
            raise ValueError(f"Invalid metric {key}={value}")


def parse(case: Case, raw: bytes, json_path: Path | None) -> dict:
    if case.group == "dispatch":
        match = DISPATCH_LINE.fullmatch(raw.decode("utf8").strip())
        if not match or json_path is None:
            raise ValueError("Invalid dispatch output")
        output = {"bars": int(match[1]), "appendMs": float(match[2]), "resultBytes": int(match[3])}
        data = json_path.read_bytes()
        result = json.loads(data)
        if output["bars"] != case.bars or output["resultBytes"] != len(data):
            raise ValueError("Dispatch bar or output length mismatch")
        if len(result["plots"]) != 1 or len(result["plots"][0]["values"]) != case.bars:
            raise ValueError("Dispatch output lost plot values")
        output["publicJsonSha256"] = hashlib.sha256(data).hexdigest()
        check_numbers(output)
        return output
    lines = json_lines(raw)
    if case.group == "heap":
        if len(lines) != 1:
            raise ValueError("Heap probe must return exactly one record")
        output = lines[0]
        if output["bars"] != case.bars or output["mode"] != case.mode:
            raise ValueError("Heap bar or mode mismatch")
        required = {"retainedHeapBytes"}
        if case.mode == "historical":
            required |= {"seedMs", "seedAllocatedBytes", "seedAllocations", "rollingWindowValues",
                         "rollingWindowValueCapacity", "cloneHeapBytes", "cloneAllocations",
                         "cloneMedianMs", "resultHeapBytes", "resultMs"}
        else:
            required |= {"applyUpdateMedianMs", "updateMedianMs", "applyAllocatedMedianBytes", "updateAllocatedMedianBytes"}
        if not required <= output.keys():
            raise ValueError("Missing heap metrics")
        check_numbers(output)
        return output
    expected = ["dataset", "analyze", "init", "seed"] + (
        ["hostJsonPipeline", "parseJson"] if case.mode == "pipeline" else
        ["cowClone", "ownedResult", "serializeOwnedResult", "parseJson"]
    )
    if [line.get("stage") for line in lines[:-1]] != expected:
        raise ValueError("Result stage order or count mismatch")
    output = lines[-1]
    if output["bars"] != case.bars or output["mode"] != case.mode or output["jsonBytes"] <= 0:
        raise ValueError("Invalid result summary")
    for line in lines:
        check_numbers(line)
    return {"stages": lines[:-1], "output": output}


def metric_summary(before: list[dict], after: list[dict], exclude: set[str]) -> dict:
    keys = {key for key, value in before[0].items() if numeric(value) and key not in exclude}
    for record in before + after:
        other = {key for key, value in record.items() if numeric(value) and key not in exclude}
        if other != keys:
            raise ValueError("Inconsistent metric keys; refusing a selective summary")
    summary = {}
    for key in sorted(keys):
        b = [record[key] for record in before]
        a = [record[key] for record in after]
        bm, am = statistics.median(b), statistics.median(a)
        summary[key] = {"beforeMedian": bm, "afterMedian": am,
                        "afterBeforeRatio": am / bm if bm else None,
                        "beforeSamples": b, "afterSamples": a}
    return summary


def summaries(cases: list[Case], rows: list[dict]) -> dict:
    result = {}
    for case in cases:
        data = {tag: [row["metrics"] for row in rows if row["case"] == case.name and row["tag"] == tag] for tag in TAGS}
        if any(len(records) != case.repetitions for records in data.values()):
            raise ValueError(f"Incomplete case: {case.name}")
        entry = {"group": case.group, "bars": case.bars, "mode": case.mode,
                 "freshProcessesPerVersion": case.repetitions}
        if case.group == "result":
            entry["stages"] = {}
            for index, stage in enumerate(data["before"][0]["stages"]):
                entry["stages"][stage["stage"]] = metric_summary(
                    [record["stages"][index] for record in data["before"]],
                    [record["stages"][index] for record in data["after"]], {"bars"})
            entry["output"] = metric_summary(
                [record["output"] for record in data["before"]],
                [record["output"] for record in data["after"]], {"bars"})
            sizes = {record["output"]["jsonBytes"] for records in data.values() for record in records}
            if len(sizes) != 1:
                raise ValueError(f"Result JSON byte count differs: {case.name}")
            entry["outputByteCountEqual"] = True
            entry["fullOutputParity"] = "Not established by this result probe; see differential runner."
        else:
            entry["metrics"] = metric_summary(data["before"], data["after"], {"bars"})
            if case.group == "dispatch":
                hashes = {record["publicJsonSha256"] for records in data.values() for record in records}
                if len(hashes) != 1:
                    raise ValueError("Dispatch full output differs across processes or versions")
                entry["fullOutputParity"] = True
                entry["publicJsonSha256"] = hashes.pop()
        result[case.name] = entry
    return result


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--group", choices=("heap", "dispatch", "result", "all"), default="all")
    parser.add_argument("--include-unchanged-controls", action="store_true")
    parser.add_argument("--prepare-only", action="store_true")
    parser.add_argument("--timeout", type=float, default=300)
    args = parser.parse_args()
    cases, scripts = plan(args.include_unchanged_controls)
    prepare_scripts(scripts)
    cases = [case for case in cases if args.group == "all" or case.group == args.group]
    planned = sum(2 * case.repetitions for case in cases)
    if args.prepare_only:
        print(json.dumps({"cases": len(cases), "plannedProcesses": planned, "benchmarksExecuted": False}))
        return
    groups = sorted({case.group for case in cases})
    identities = {group: {tag: identity(group, tag) for tag in TAGS} for group in groups}
    sources = {case.script: {"path": str(DIRECTORY / case.script), "sha256": digest(DIRECTORY / case.script)} for case in cases}
    source_receipts = {str(path.relative_to(DIRECTORY)): digest(path) for path in
                       (DIRECTORY / "before-source-identity.json", DIRECTORY / "after-source-identity.json") if path.exists()}
    run_id = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S.%fZ") + "-" + uuid.uuid4().hex[:8]
    out = DIRECTORY / "benchmark-receipts" / f"{args.group}-{run_id}"
    out.mkdir(parents=True, exist_ok=False)
    rows: list[dict] = []
    receipt = {"status": "running", "group": args.group, "runId": run_id,
               "method": "3 fresh processes per version and case, alternating order; staged result attribution is 1 per version",
               "allocatorAccounting": "Requested allocation sizes; retained live and logical peak exclude allocator overhead. Result probe also records RSS.",
               "limitations": ["Descriptive medians, not release qualification or strict worst-case algorithm bounds.",
                               "Heap probe price bars repeat every 17 bars; separate monotonic candidates test large retained queues.",
                               "Result JSON byte counts alone are not full parity; separate differential outputs establish that."],
               "plannedProcesses": planned, "identities": identities, "sources": sources,
               "sourceReceiptSha256": source_receipts, "runnerSha256": digest(Path(__file__)), "records": rows}
    write_json(out / "progress.json", receipt)
    try:
        for repetition in range(REPETITIONS):
            for case in cases:
                if repetition >= case.repetitions:
                    continue
                order = TAGS if repetition % 2 == 0 else tuple(reversed(TAGS))
                for tag in order:
                    stem = f"{case.name}-{tag}-{repetition}"
                    binary = Path(identities[case.group][tag]["binary"])
                    script = DIRECTORY / case.script
                    json_path = out / f"{stem}.public.json" if case.group == "dispatch" else None
                    if case.group == "heap":
                        command = [str(binary), str(script), str(case.bars), case.mode]
                    elif case.group == "dispatch":
                        command = [str(binary), str(case.bars), str(json_path)]
                    else:
                        command = [str(binary), str(script), case.mode, str(case.bars)]
                    row = {"case": case.name, "group": case.group, "tag": tag, "repetition": repetition,
                           "command": command, "binarySha256": identities[case.group][tag]["binarySha256"],
                           "scriptSha256": sources[case.script]["sha256"]}
                    start = time.monotonic()
                    try:
                        process = subprocess.run(command, cwd=ROOT, capture_output=True, timeout=args.timeout)
                        raw, errors, code = process.stdout, process.stderr, process.returncode
                    except subprocess.TimeoutExpired as error:
                        raw, errors, code = error.stdout or b"", error.stderr or b"", None
                        row["timeout"] = args.timeout
                    (out / f"{stem}.stdout").write_bytes(raw)
                    (out / f"{stem}.stderr").write_bytes(errors)
                    row.update(returncode=code, wallSeconds=time.monotonic() - start,
                               stdoutSha256=hashlib.sha256(raw).hexdigest(), stderrSha256=hashlib.sha256(errors).hexdigest(),
                               stdoutReceipt=f"{stem}.stdout", stderrReceipt=f"{stem}.stderr")
                    rows.append(row)
                    write_json(out / f"{stem}.execution.json", row)
                    write_json(out / "progress.json", receipt)
                    if code != 0:
                        raise RuntimeError(f"Probe failed ({code}): {stem}; receipts: {out}")
                    row["metrics"] = parse(case, raw, json_path)
                    write_json(out / f"{stem}.execution.json", row)
                    write_json(out / "progress.json", receipt)
                    if case.group == "result":
                        report = {stage["stage"]: stage["ms"] for stage in row["metrics"]["stages"]}
                    else:
                        report = {key: value for key, value in row["metrics"].items() if key.endswith("Ms")}
                    print(case.name, tag, repetition, json.dumps(report), flush=True)
        for group in groups:
            for tag in TAGS:
                if identity(group, tag) != identities[group][tag]:
                    raise RuntimeError(f"Binary/source/link receipt changed during run: {group}/{tag}")
        for source in sources.values():
            if digest(Path(source["path"])) != source["sha256"]:
                raise RuntimeError(f"Script changed during run: {source['path']}")
        receipt.update(status="passed", completedProcesses=len(rows), summary=summaries(cases, rows))
        if len(rows) != planned:
            raise RuntimeError("Process count mismatch")
        write_json(out / "summary.json", receipt)
        write_json(DIRECTORY / f"benchmark-{args.group}-results.json", receipt)
        write_json(out / "progress.json", receipt)
        print(f"PASS {len(cases)} cases / {planned} fresh processes; {out / 'summary.json'}", flush=True)
    except BaseException as error:
        receipt.update(status="failed", completedProcesses=len(rows), error=str(error))
        write_json(out / "failure.json", receipt)
        write_json(out / "progress.json", receipt)
        raise


if __name__ == "__main__":
    main()

